import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { toast } from '../libs/toast';
import { FaPlus, FaTrash } from 'react-icons/fa';

const Roles: React.FC = () => {
  const [roles, setRoles] = useState<any[]>([]);
  const [code, setCode] = useState('');
  const [name, setName] = useState('');
  const [rank, setRank] = useState<number | ''>('');
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem('token');
  const authHeaders = token ? { Authorization: `Bearer ${token}` } : undefined;

  useEffect(() => { fetchRoles(); }, []);

  const fetchRoles = async () => {
    try {
      const res = await axios.get('/api/roles');
      setRoles(res.data);
    } catch (e) {
      toast.error('خطا در دریافت نقش‌ها');
    } finally {
      setLoading(false);
    }
  };

  const addRole = async () => {
    if (!code.trim() || !name.trim()) {
      toast.error('کد و نام نقش الزامی است');
      return;
    }
    const rankValue = typeof rank === 'number' ? rank : 999;
    try {
      await axios.post('/api/roles', { code, name, rank: rankValue }, { headers: authHeaders });
      toast.success('نقش با موفقیت ثبت شد');
      setCode('');
      setName('');
      setRank('');
      fetchRoles();
    } catch (e) {
      toast.error('ثبت نقش با خطا مواجه شد');
    }
  };

  const deleteRole = async (id: number) => {
    if (!window.confirm('از حذف نقش مطمئن هستید؟')) return;
    try {
      await axios.delete(`/api/roles/${id}`, { headers: authHeaders });
      toast.success('نقش حذف شد');
      fetchRoles();
    } catch (e) {
      toast.error('حذف نقش با خطا مواجه شد');
    }
  };

  if (loading) {
    return <div className="loading-container"><div className="loading-spinner"></div><p>در حال بارگذاری...</p></div>;
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h1>مدیریت نقش‌ها</h1>
      </div>

      <div className="form-card">
        <div className="form-row">
          <label>کد نقش</label>
          <input value={code} onChange={(e) => setCode(e.target.value)} placeholder="مثلاً cameraman" />
        </div>
      <div className="form-row">
        <label>نام نقش</label>
        <input value={name} onChange={(e) => setName(e.target.value)} placeholder="مثلاً تصویربردار" />
      </div>
      <div className="form-row">
        <label>رتبه (سلسله‌مراتبی)</label>
        <input type="number" value={rank} onChange={(e) => setRank(e.target.value ? Number(e.target.value) : '')} placeholder="مثلاً 1 برای تهیه‌کننده" />
        <small className="muted">عدد کوچکتر یعنی جایگاه بالاتر؛ اگر ندهید 999 در نظر گرفته می‌شود.</small>
      </div>
      <button className="btn btn-success" onClick={addRole}><FaPlus /> افزودن نقش</button>
    </div>

      <div className="list-card">
        {roles.length === 0 ? (
          <p>نقشی ثبت نشده است.</p>
        ) : (
          <table className="data-table">
          <thead>
            <tr>
              <th>کد</th>
              <th>نام</th>
              <th>رتبه</th>
              <th>عملیات</th>
            </tr>
          </thead>
          <tbody>
            {roles.map((r) => (
              <tr key={r.id}>
                <td>{r.code}</td>
                <td>{r.name}</td>
                <td>{r.rank ?? 999}</td>
                <td>
                  <button className="action-btn delete" onClick={() => deleteRole(r.id)} title="حذف"><FaTrash /></button>
                </td>
              </tr>
            ))}
          </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default Roles;
